# Helpers
exceptions = []
def log(case_ref, table, column, value, issue, severity="ACTION"):
    exceptions.append({"severity": severity, "caseReference": case_ref, "table": table, "column": column,
                       "value": None if value is None else str(value)[:300], "issue": issue})

extra_notes = []   # text found in date fields etc, moved to S62aCaseNote

def blank(v):
    return v is None or (isinstance(v, float) and pd.isna(v)) or str(v).strip() in ("", "nan", "NaT", "None")

def clean(v):
    if blank(v):
        return None
    if isinstance(v, str):
        v = v.strip()
        if FLATTEN_NEWLINES:
            v = re.sub(r"\s*[\r\n]+\s*", " | ", v)
    return v

DATE_IN_TEXT = re.compile(r"\b(\d{1,2}/\d{1,2}/\d{2,4})\b")

def to_date(v, ref=None, table=None, col=None):
    if blank(v):
        return None
    if isinstance(v, (datetime, pd.Timestamp)):
        return pd.Timestamp(v).strftime("%Y-%m-%d")
    text = str(v).strip()
    d = pd.to_datetime(text, dayfirst=True, errors="coerce")
    if not pd.isna(d):
        return d.strftime("%Y-%m-%d")
    m = DATE_IN_TEXT.search(text)
    if m:
        d = pd.to_datetime(m.group(1), dayfirst=True, errors="coerce")
        if not pd.isna(d):
            extra_notes.append({"caseReference": ref, "noteType": col, "noteText": f"{col}: {clean(text)}"})
            log(ref, table, col, v, "Date taken from text, full text kept in S62aCaseNote", "INFO")
            return d.strftime("%Y-%m-%d")
    if KEEP_DATELESS_TEXT_AS_NOTE:
        extra_notes.append({"caseReference": ref, "noteType": col, "noteText": f"{col}: {clean(text)}"})
        log(ref, table, col, v, "No date in value, set to null, text kept in S62aCaseNote", "INFO")
    else:
        log(ref, table, col, v, "No date in value, set to null, text removed", "INFO")
    return None

def split_multi(v):
    """'[a, b]' or '{a, b}' -> ['a','b'];  'a; b' -> ['a','b'];  scalar -> [scalar]."""
    if blank(v):
        return []
    s = str(v).strip()
    m = re.match(r"^[\[{](.*)[\]}]$", s, re.S)
    if m:
        return [x.strip() or None for x in m.group(1).split(",")]
    if ";" in s:
        return [x.strip() or None for x in s.split(";")]
    return [v]

def is_date_field(name):
    return bool(re.search(r"date$|Date$", str(name)))

def get(row, col):
    return row[col] if col in row.index else None

# 1b. Notes: one row per note column with a value
note_rows = []
for _, row in cases.iterrows():
    for c in note_cols:
        v = get(row, c)
        if not blank(v):
            text = clean(to_date(v) if isinstance(v, (datetime, pd.Timestamp)) else v)
            note_rows.append({"caseReference": row["Case reference"], "noteType": c, "noteText": f"{c}: {text}"})

# 3. Contacts + addresses (agent, applicant, site). Multiple people per cell split on ';'
contact_rows, address_rows = [], []
for _, row in cases.iterrows():
    ref = row["Case reference"]
    for role in ["Agent", "Applicant"]:
        parts = {k: split_multi(get(row, f"{role} {k}")) for k in ["first name", "last name", "email", "phone"]}
        org = get(row, f"{role} organisation name")
        n = max([len(v) for v in parts.values()] + [1 if not blank(org) else 0])
        lens = {k: len(v) for k, v in parts.items() if len(v) > 1}
        if len(set(lens.values())) > 1:
            log(ref, "Contact", role, lens, "Multi-person cells have different counts, aligned by position")
        for i in range(n):
            pick = lambda k: parts[k][i] if i < len(parts[k]) else None
            email = pick("email")
            contact_rows.append({
                "caseReference": ref, "contactRole": role, "sequence": i + 1,
                "orgName": clean(org) if i == 0 else None,
                "firstName": clean(pick("first name")), "lastName": clean(pick("last name")),
                "email": clean(re.sub(r"^mailto:", "", str(email), flags=re.I)) if not blank(email) else None,
                "telephoneNumber": clean(pick("phone")),
                "applicantType": clean(get(row, "Applicant type")) if role == "Applicant" and i == 0 else None,
            })
    for role, cols in {
        "Agent":     ["Agent address 1", "Agent address 2", "Agent town or city", "Agent county", "Agent postcode"],
        "Applicant": ["Applicant address 1", "Applicant address 2", "Applicant town or city", "Applicant county", "Applicant postcode"],
        "Site":      ["Site address 1", "Site address 2", "Site town or city", "Site county", "Site post code"],
    }.items():
        vals = [clean(get(row, c)) for c in cols]
        if any(v is not None for v in vals):
            address_rows.append(dict(zip(["caseReference", "addressType", "line1", "line2", "townCity", "county", "postcode"],
                                         [ref, role] + vals)))
tables["Contact"] = contact_rows
tables["Address"] = address_rows

