EVENTS = {
    "SiteVisit":         {"Site visit type": "siteVisitType", "Site visit date": "eventDate"},
    "ProcedureNotice":   {"Notice of procedure date": "eventDate"},
    "Hearing":           {"Hearing  date": "eventDate", "Hearing notification date": "notificationDate",
                          "Hearing issues report published date": "issuesReportPublishedDate",
                          "Hearing duration - prep (days)": "prepDuration",
                          "Hearing duration - sitting (days)": "sittingDuration",
                          "Hearing duration - reporting (days)": "reportingDuration", "Hearing venue": "venue"},
    "AdditionalMeeting": {"Additional meeting required date": "eventDate"},
}
event_rows = []
for _, row in cases.iterrows():
    for etype, cols in EVENTS.items():
        if all(blank(get(row, c)) for c in cols):
            continue
        rec = {"caseReference": row["Case reference"], "eventType": etype}
        for c, f in cols.items():
            v = get(row, c)
            rec[f] = to_date(v, row["Case reference"], "S62aEvent", c) if "Date" in f or f == "eventDate" else clean(v)
        event_rows.append(rec)
tables["S62aEvent"] = event_rows

# 6. Repeating groups: explode '[a, b]' / '{a, b}' cells into child rows
def derive_parking(lists, ambiguous, n):
    """existing + difference = proposed, so a missing one can be rebuilt when the other two line up."""
    def nums(f):
        v = lists.get(f, [])
        try:
            return [float(x) for x in v] if len(v) == n and f not in ambiguous else None
        except (TypeError, ValueError):
            return None
    rules = {"existingSpaces":  lambda p, e, d: [a - b for a, b in zip(p, d)] if p and d else None,
             "proposedSpaces":  lambda p, e, d: [a + b for a, b in zip(e, d)] if e and d else None,
             "spaceDifference": lambda p, e, d: [a - b for a, b in zip(p, e)] if p and e else None}
    resolved = {}
    for f, rule in rules.items():
        if f not in ambiguous:
            continue
        derived = rule(nums("proposedSpaces"), nums("existingSpaces"), nums("spaceDifference"))
        original = {float(x) for x in ambiguous[f] if not blank(x)}
        if derived and original <= set(derived):
            resolved[f] = [int(x) if x == int(x) else x for x in derived]

    # single leftover values: try each group position (0 elsewhere) and keep a placement where
    # existing + difference = proposed holds for every group; first-group placement preferred
    singles = [f for f in ("existingSpaces", "proposedSpaces", "spaceDifference")
               if f in ambiguous and f not in resolved and len(ambiguous[f]) == 1]
    if singles:
        from itertools import product
        def as_list(f, pos=None):
            if f in resolved:
                return [float(x) for x in resolved[f]]
            if f in singles:
                return [float(ambiguous[f][0]) if i == pos else 0.0 for i in range(n)]
            return nums(f)
        for combo in product(range(n), repeat=len(singles)):
            pos = dict(zip(singles, combo))
            e, p_, d = (as_list(f, pos.get(f)) for f in ("existingSpaces", "proposedSpaces", "spaceDifference"))
            try:
                if e and p_ and d and all(a + b == c for a, b, c in zip(e, d, p_)):
                    for f in singles:
                        resolved[f] = [int(x) if x == int(x) else x for x in as_list(f, pos[f])]
                    break
            except (TypeError, ValueError):
                break
    return resolved

COUNT_FIELDS = {"existingSpaces", "proposedSpaces", "spaceDifference", "bedroomsOne", "bedroomsTwo", "bedroomsThree",
                "bedroomsFourPlus", "bedroomsUnknown", "totalUnits", "netAdditionalGross", "existingGross",
                "grossLost", "grossProposed", "voidCapacity", "maxAnnualThroughput"}

def explode_group(table, cols, extra=None, derive=None):
    """Horizon joins each attribute as a DISTINCT list with nulls dropped, so values can only be
    matched to groups when an attribute has one value per group. Anything else is ambiguous:
    left null and logged, to be fixed from row-level Horizon data."""
    rows = []
    id_col = "groupId" if "groupId" in cols.values() else None
    for _, row in cases.iterrows():
        ref = row["Case reference"]
        lists = {f: split_multi(get(row, c)) for c, f in cols.items()}
        n = (len(lists[id_col]) if id_col else 0) or max(len(v) for v in lists.values())
        if n == 0:
            continue
        ambiguous = {f: v for f, v in lists.items() if f != id_col and 0 < len(v) != n}
        if derive and ambiguous:
            for f, vals in derive(lists, ambiguous, n).items():
                log(ref, table, f, ambiguous.pop(f), f"Rebuilt from the other parking columns: {vals}", "INFO")
                lists[f] = vals
        # single value for several groups: text -> same value on every group; number -> first group, 0 on the rest
        for f in [f for f, v in ambiguous.items() if len(v) == 1]:
            v = ambiguous.pop(f)[0]
            if f in COUNT_FIELDS:
                lists[f] = [v] + [0] * (n - 1)
                log(ref, table, f, v, f"Assumed: single value put on group 1, 0 on the other {n - 1} group(s)", "INFO")
            else:
                lists[f] = [v] * n
                log(ref, table, f, v, f"Assumed: single value applies to all {n} groups", "INFO")
        for f, v in ambiguous.items():
            filled = "set to 0" if NULL_COUNTS_TO_ZERO and f in COUNT_FIELDS else "left null"
            log(ref, table, f, get(row, next(c for c, ff in cols.items() if ff == f)),
                f"Ambiguous: {len(v)} values for {n} groups, {filled}; source values not migrated (check Horizon)")
        for i in range(n):
            rec = {"caseReference": ref, "sequence": i + 1, **(extra or {})}
            for f, vals in lists.items():
                rec[f] = clean(vals[i]) if f not in ambiguous and i < len(vals) else None
            if any(rec[f] is not None for f in lists if f != id_col) or ambiguous:
                if NULL_COUNTS_TO_ZERO:
                    for f in lists:
                        if f in COUNT_FIELDS and rec[f] is None:
                            rec[f] = 0
                rows.append(rec)
    return rows

tables["S62aVehicleParking"] = explode_group("S62aVehicleParking", {
